5	+++ b/apps/obsidian/src/components/canvas/TextLinkDialog.tsx
6	@@ -0,0 +1,226 @@
7	+import { useCallback, useEffect, useRef, useState } from "react";
8	+import {
9	+  TLBaseShape,
10	+  TLShape,
11	+  TldrawUiButton,
12	+  TldrawUiButtonLabel,
13	+  TldrawUiDialogBody,
14	+  TldrawUiDialogCloseButton,
15	+  TldrawUiDialogFooter,
16	+  TldrawUiDialogHeader,
17	+  TldrawUiDialogTitle,
18	+  TldrawUiInput,
19	+  track,
20	+  useEditor,
21	+} from "tldraw";
22	+import {
23	+  getTextShapeLinkUrl,
24	+  isAllowedTextLinkUrl,
25	+  isObsidianUrl,
26	+} from "~/components/canvas/utils/textShapeLink";
27	+
28	+type ShapeWithUrl = TLBaseShape<string, { url: string }>;
29	+
30	+// Text shapes keep their link in `meta` so the stock props schema is untouched;
31	+// every other shape type uses tldraw's own `props.url`.
32	+const isTextShape = (shape: TLShape): boolean => shape.type === "text";
33	+
34	+const linkPatch = (shape: TLShape, url: string) =>
35	+  isTextShape(shape) ? { meta: { url } } : { props: { url } };
36	+
37	+const readLinkUrl = (shape: TLShape): string =>
38	+  isTextShape(shape)
39	+    ? getTextShapeLinkUrl(shape)
40	+    : (((shape.props as { url?: unknown }).url as string | undefined) ?? "");
41	+
42	+// Declared as a function property rather than reusing TLUiDialogProps, whose
43	+// method-shorthand onClose trips @typescript-eslint/unbound-method.
44	+type TextLinkDialogProps = { onClose: () => void };
45	+
46	+type UrlValidity = { isValid: boolean; hasProtocol: boolean };
47	+
48	+// Bookmarks link their title with a raw <a href>, not HyperlinkButton, so a
49	+// page link there would reach the OS handler and skip the vault check.
50	+const acceptsPageLinks = (shapeType: string): boolean =>
51	+  shapeType !== "bookmark";
52	+
53	+// Every shape type uses tldraw's linkUrl, patched to accept obsidian://open links.
54	+const validateUrl = (url: string, shapeType: string): UrlValidity => {
55	+  // Checked before the https:// fallback, which would accept `https://obsidian://…`.
56	+  if (!acceptsPageLinks(shapeType) && isObsidianUrl(url))
57	+    return { isValid: false, hasProtocol: false };
58	+  if (isAllowedTextLinkUrl(url)) return { isValid: true, hasProtocol: true };
59	+  if (isAllowedTextLinkUrl(`https://${url}`))
60	+    return { isValid: true, hasProtocol: false };
61	+  return { isValid: false, hasProtocol: false };
62	+};
63	+
64	+// A fork of tldraw's EditLinkDialog, which is not exported. Copy differs: the
65	+// original's msg() keys are inlined, as this app has no i18n layer.
66	+export const TextLinkDialog = track(({ onClose }: TextLinkDialogProps) => {
67	+  const editor = useEditor();
68	+  const selectedShape = editor.getOnlySelectedShape();
69	+
70	+  const canEditLink =
71	+    selectedShape &&
72	+    (isTextShape(selectedShape) ||
73	+      ("url" in selectedShape.props &&
74	+        typeof selectedShape.props.url === "string"));
75	+
76	+  if (!canEditLink) return null;
77	+
78	+  return (
79	+    <TextLinkDialogInner
80	+      key={selectedShape.id}
81	+      onClose={onClose}
82	+      selectedShape={selectedShape as ShapeWithUrl}
83	+    />
84	+  );
85	+});
86	+
87	+const TextLinkDialogInner = track(
88	+  ({
89	+    onClose,
90	+    selectedShape,
91	+  }: TextLinkDialogProps & { selectedShape: ShapeWithUrl }) => {
92	+    const editor = useEditor();
93	+    const rInput = useRef<HTMLInputElement | null>(null);
94	+    const shapeType = selectedShape.type;
95	+
96	+    useEffect(() => {
97	+      editor.timers.requestAnimationFrame(() => rInput.current?.focus());
98	+    }, [editor]);
99	+
100	+    const rInitialValue = useRef(readLinkUrl(selectedShape));
101	+
102	+    const [urlInputState, setUrlInputState] = useState(() => {
103	+      const initialUrl = readLinkUrl(selectedShape);
104	+      const result = validateUrl(initialUrl, shapeType);
105	+      const initialValue = result.isValid
106	+        ? result.hasProtocol
107	+          ? initialUrl
108	+          : `https://${initialUrl}`
109	+        : "https://";
110	+      return { actual: initialValue, safe: initialValue, valid: true };
111	+    });
112	+
113	+    const handleChange = useCallback(
114	+      (rawValue: string) => {
115	+        // Auto-correct a doubled https:// from a bad paste.
116	+        const fixedRawValue = rawValue.replace(
117	+          /https?:\/\/(https?:\/\/)/,
118	+          (_match, arg1: string) => arg1,
119	+        );
120	+        const result = validateUrl(fixedRawValue, shapeType);
121	+        const safeValue = result.isValid
122	+          ? result.hasProtocol
123	+            ? fixedRawValue
124	+            : `https://${fixedRawValue}`
125	+          : "https://";
126	+
127	+        setUrlInputState({
128	+          actual: fixedRawValue,
129	+          safe: safeValue,
130	+          valid: result.isValid,
131	+        });
132	+      },
133	+      [shapeType],
134	+    );
135	+
136	+    const handleClear = useCallback(() => {
137	+      const onlySelectedShape = editor.getOnlySelectedShape();
138	+      if (!onlySelectedShape) return;
139	+      editor.updateShapes([
140	+        {
141	+          id: onlySelectedShape.id,
142	+          type: onlySelectedShape.type,
143	+          ...linkPatch(onlySelectedShape, ""),
144	+        },
145	+      ]);
146	+      onClose();
147	+    }, [editor, onClose]);
148	+
149	+    const handleComplete = useCallback(() => {
150	+      // Enter reaches this even while Save is disabled, and the fallback
151	+      // "https://" fails both validators.
152	+      if (!urlInputState.valid) return;
153	+      const onlySelectedShape = editor.getOnlySelectedShape();
154	+      if (!onlySelectedShape) return;
155	+      if (readLinkUrl(onlySelectedShape) !== urlInputState.safe) {
156	+        editor.updateShapes([
157	+          {
158	+            id: onlySelectedShape.id,
159	+            type: onlySelectedShape.type,
160	+            ...linkPatch(onlySelectedShape, urlInputState.safe),
161	+          },
162	+        ]);
163	+      }
164	+      onClose();
165	+    }, [editor, onClose, urlInputState]);
166	+
167	+    const handleCancel = useCallback(() => {
168	+      onClose();
169	+    }, [onClose]);
170	+
171	+    const isRemoving = rInitialValue.current && !urlInputState.valid;
172	+
173	+    return (
174	+      <>
175	+        <TldrawUiDialogHeader>
176	+          <TldrawUiDialogTitle>Edit link</TldrawUiDialogTitle>
177	+          <TldrawUiDialogCloseButton />
178	+        </TldrawUiDialogHeader>
179	+        <TldrawUiDialogBody>
180	+          <div className="tlui-edit-link-dialog">
181	+            <TldrawUiInput
182	+              ref={rInput}
183	+              className="tlui-edit-link-dialog__input"
184	+              label="edit-link-dialog.url"
185	+              autoFocus
186	+              autoSelect
187	+              placeholder="https://example.com"
188	+              value={urlInputState.actual}
189	+              onValueChange={handleChange}
190	+              onComplete={handleComplete}
191	+              onCancel={handleCancel}
192	+            />
193	+            <div>
194	+              {!urlInputState.valid
195	+                ? "Invalid URL"
196	+                : acceptsPageLinks(shapeType)
197	+                  ? "Enter a URL, or an obsidian:// link to a page."
198	+                  : "Enter a URL."}
199	+            </div>
200	+          </div>
201	+        </TldrawUiDialogBody>
202	+        <TldrawUiDialogFooter className="tlui-dialog__footer__actions">
203	+          <TldrawUiButton
204	+            type="normal"
205	+            onClick={handleCancel}
206	+            onTouchEnd={handleCancel}
207	+          >
208	+            <TldrawUiButtonLabel>Cancel</TldrawUiButtonLabel>
209	+          </TldrawUiButton>
210	+          {isRemoving ? (
211	+            <TldrawUiButton
212	+              type="danger"
213	+              onClick={handleClear}
214	+              onTouchEnd={handleClear}
215	+            >
216	+              <TldrawUiButtonLabel>Clear</TldrawUiButtonLabel>
217	+            </TldrawUiButton>
218	+          ) : (
219	+            <TldrawUiButton
220	+              type="primary"
221	+              disabled={!urlInputState.valid}
222	+              onClick={handleComplete}
223	+              onTouchEnd={handleComplete}
224	+            >
225	+              <TldrawUiButtonLabel>Save</TldrawUiButtonLabel>
226	+            </TldrawUiButton>
227	+          )}
228	+        </TldrawUiDialogFooter>
229	+      </>
230	+    );
231	+  },
232	+);
