297	@@ -0,0 +1,59 @@
298	+import { HyperlinkButton, useEditor, useValue, TLShapeId } from "tldraw";
299	+import { getTextShapeLinkUrl } from "~/components/canvas/utils/textShapeLink";
300	+
301	+// Matches tldraw's own HyperlinkButton, which hides itself when zoomed out.
302	+const HIDE_BELOW_ZOOM = 0.32;
303	+
304	+type TextLink = { id: TLShapeId; url: string; left: number; top: number };
305	+
306	+// Rendered here, not on a custom shape util, so the stock text shape stays
307	+// untouched -- at the cost of rotation, frame clipping and stacking fidelity.
308	+export const TextLinkOverlay = () => {
309	+  const editor = useEditor();
310	+
311	+  const links = useValue<TextLink[]>(
312	+    "textShapeLinks",
313	+    () => {
314	+      if (editor.getZoomLevel() < HIDE_BELOW_ZOOM) return [];
315	+      const viewport = editor.getViewportPageBounds();
316	+      return editor.getCurrentPageShapes().flatMap<TextLink>((shape) => {
317	+        if (shape.type !== "text" || editor.isShapeHidden(shape)) return [];
318	+        const url = getTextShapeLinkUrl(shape);
319	+        if (!url) return [];
320	+        const bounds = editor.getShapePageBounds(shape.id);
321	+        if (!bounds || !viewport.includes(bounds)) return [];
322	+        const topRight = editor.pageToViewport({
323	+          x: bounds.maxX,
324	+          y: bounds.minY,
325	+        });
326	+        const bottomRight = editor.pageToViewport({
327	+          x: bounds.maxX,
328	+          y: bounds.maxY,
329	+        });
330	+        return [
331	+          {
332	+            id: shape.id,
333	+            url,
334	+            left: topRight.x,
335	+            top: (topRight.y + bottomRight.y) / 2,
336	+          },
337	+        ];
338	+      });
339	+    },
340	+    [editor],
341	+  );
342	+
343	+  return (
344	+    <div className="dg-text-link-overlay">
345	+      {links.map(({ id, url, left, top }) => (
346	+        <div
347	+          key={id}
348	+          className="dg-text-link-anchor"
349	+          style={{ left: `${left}px`, top: `${top}px` }}
350	+        >
351	+          <HyperlinkButton url={url} />
352	+        </div>
353	+      ))}
354	+    </div>
355	+  );
356	+};
