418	@@ -0,0 +1,66 @@
419	+import type { Editor } from "tldraw";
420	+import DiscourseGraphPlugin from "~/index";
421	+import {
422	+  parseObsidianOpenUrl,
423	+  resolveObsidianUrlToFile,
424	+} from "~/components/canvas/utils/externalContentHandlers";
425	+import {
426	+  openFileInNewLeaf,
427	+  openFileInNewTab,
428	+  openFileInSidebar,
429	+} from "~/components/canvas/utils/openFileUtils";
430	+import { showToast } from "~/components/canvas/utils/toastUtils";
431	+import { isObsidianUrl } from "~/components/canvas/utils/textShapeLink";
432	+
433	+type NavigateLinkDetail = {
434	+  url: string;
435	+  metaKey: boolean;
436	+  ctrlKey: boolean;
437	+  altKey: boolean;
438	+};
439	+
440	+// Patched tldraw dispatches this from every HyperlinkButton, so one listener
441	+// covers text-shape links and geo/note/image links alike.
442	+export const NAVIGATE_LINK_EVENT = "tldraw.navigate-link";
443	+
444	+export const registerLinkNavigation = (
445	+  editor: Editor,
446	+  plugin: DiscourseGraphPlugin,
447	+): (() => void) => {
448	+  const container = editor.getContainer();
449	+
450	+  const onNavigate = (event: Event) => {
451	+    const { url, metaKey, ctrlKey, altKey } = (
452	+      event as CustomEvent<NavigateLinkDetail>
453	+    ).detail;
454	+    if (!isObsidianUrl(url)) return;
455	+    // Cancelling tells tldraw to preventDefault, so the URI never reaches the
456	+    // OS handler and we keep the cross-vault check below.
457	+    event.preventDefault();
458	+
459	+    // The validator parses with `new URL`, so geo links may be stored as
460	+    // `Obsidian://…` or with leading spaces; the parser expects the normal form.
461	+    const parsed = parseObsidianOpenUrl(new URL(url).toString());
462	+    const file = parsed ? resolveObsidianUrlToFile(plugin, parsed) : null;
463	+    if (!file) {
464	+      showToast({
465	+        severity: "warning",
466	+        title: "Cannot open link",
467	+        description: "The linked file is not in this vault",
468	+      });
469	+      return;
470	+    }
471	+
472	+    // Mirrors the discourse-node gestures in TldrawViewComponent.
473	+    const open = altKey
474	+      ? openFileInNewLeaf
475	+      : metaKey || ctrlKey
476	+        ? openFileInNewTab
477	+        : openFileInSidebar;
478	+    void open(plugin.app, file);
479	+    editor.selectNone();
480	+  };
481	+
482	+  container.addEventListener(NAVIGATE_LINK_EVENT, onNavigate);
483	+  return () => container.removeEventListener(NAVIGATE_LINK_EVENT, onNavigate);
484	+};
485	diff --git a/apps/obsidian/src/components/canvas/utils/textShapeLink.ts b/apps/obsidian/src/components/canvas/utils/textShapeLink.ts
