487	index 00000000..4c9159fd
488	--- /dev/null
489	+++ b/apps/obsidian/src/components/canvas/utils/textShapeLink.ts
490	@@ -0,0 +1,26 @@
491	+import { T, type TLShape } from "tldraw";
492	+
493	+// The patched tldraw validator is the single definition of a valid link, so geo
494	+// shapes and text shapes agree on what obsidian:// forms are accepted.
495	+export const isAllowedTextLinkUrl = (value: string): boolean =>
496	+  T.linkUrl.isValid(value);
497	+
498	+export const isObsidianUrl = (url: string): boolean => {
499	+  try {
500	+    return new URL(url).protocol.toLowerCase() === "obsidian:";
501	+  } catch {
502	+    return false;
503	+  }
504	+};
505	+
506	+// Returns the parsed form: `new URL` strips leading control characters, so a
507	+// raw value could pass the validator and fail a prefix test further on.
508	+export const getTextShapeLinkUrl = (shape: TLShape): string => {
509	+  const raw = (shape.meta as { url?: unknown }).url;
510	+  if (typeof raw !== "string" || !isAllowedTextLinkUrl(raw)) return "";
511	+  try {
512	+    return new URL(raw).toString();
513	+  } catch {
514	+    return "";
